import React, { useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { expect, within } from 'storybook/test';
import { ZimmSubscribeModal } from './index';

const meta: Meta<typeof ZimmSubscribeModal> = {
  title: 'Forms/ZimmSubscribeModal',
  component: ZimmSubscribeModal,
};
export default meta;
type Story = StoryObj<typeof ZimmSubscribeModal>;

/**
 * Isolated mount — open by default so the panel renders without needing a trigger. Full dialog
 * mechanics (focus entry, Tab trap, scroll lock, Escape) are mutation-tested at the footer
 * assembly level (footer/index.stories.tsx's SubscribeModalOpen) and at the hook level
 * (hooks/useZimmModal.test.tsx); testing.md says prove behaviour once, at the cheapest layer.
 * This story is for components.md's per-exported-component requirement and the visual panel.
 */
export const Default: Story = {
  render: () => {
    const [isOpen, setIsOpen] = useState(true);
    return (
      <ZimmSubscribeModal
        isOpen={isOpen}
        onClose={() => setIsOpen(false)}
        onSubmit={() => setIsOpen(false)}
        privacyPolicyHref="/privacy-policy"
      />
    );
  },
  play: async () => {
    // `find*`, not `get*`: useZimmModal starts `mounted: false` and ZimmModal returns null until
    // it flips in an effect, so the portal contents do not exist on the first synchronous pass.
    // `getByRole` threw before the effect had run. Queried through document.body rather than
    // canvasElement because ZimmModal renders via createPortal — testing.md's canvasElement rule
    // can't reach a portal root, which is why the scope was already widened here.
    const doc = within(document.body);
    await expect(await doc.findByRole('dialog')).toBeInTheDocument();
    await expect(await doc.findByRole('heading', { name: /join us/i })).toBeInTheDocument();
    await expect(await doc.findByRole('link', { name: /privacy policy/i })).toBeInTheDocument();
  },
};

