describe('A1 measurement: does ZimmModal escape a story-scoped host?', () => {
  test('the dialog is NOT inside the mount container (canvasElement analogue)', () => {
    // `container` is the exact analogue of Storybook's canvasElement: the element the story
    // tree is mounted into, itself a descendant of document.body.
    const { container } = render(
      <ChakraProvider theme={theme}>
        <ZimmModal isOpen mounted onClose={() => {}} maxWidth="24rem" labelledBy="t">
          <h2 id="t">Example dialog</h2>
        </ZimmModal>
      </ChakraProvider>,
    );

    const dialog = document.body.querySelector('[role="dialog"]');
    expect(dialog).not.toBeNull();

    // MEASUREMENT 1 — the container does not contain the dialog
    expect(container.contains(dialog!)).toBe(false);
    // MEASUREMENT 2 — but document.body does
    expect(document.body.contains(dialog!)).toBe(true);
    // MEASUREMENT 3 — the dialog's portal root is body itself, not the container
    expect(dialog!.closest('[role="presentation"]')!.parentElement).toBe(document.body);
    // MEASUREMENT 4 — a canvas-scoped query finds nothing
    expect(container.querySelectorAll('[role="dialog"]').length).toBe(0);

