const OpenModalExample = () => {
  const [isOpen, setIsOpen] = useState(true);
  return (
    <ZimmModal
      isOpen={isOpen}
      mounted
      onClose={() => setIsOpen(false)}
      maxWidth="24rem"
      labelledBy="zimm-modal-story-title"
